mapper.update:
UPDATE jwt_revocation
SET token_expires_at = #{tokenExpiresAt},
    expires_at_epoch_ms = #{expiresAtEpochMs}
WHERE jti_sha256 = #{jtiSha256}
  AND expires_at_epoch_ms < #{expiresAtEpochMs}

mapper.select:
SELECT
    CASE WHEN EXISTS(
        SELECT 1
        FROM jwt_revocation r
        WHERE r.jti_sha256 = #{jtiSha256}
          AND r.expires_at_epoch_ms > #{nowEpochMs}
    ) THEN 1 ELSE 0 END AS jti_revoked,
    c.checkpoint_status,
    c.min_valid_iat_epoch_ms
FROM jwt_revocation_checkpoint c
WHERE c.checkpoint_key = #{checkpointKey}

mapper.update:
UPDATE jwt_revocation_checkpoint
SET checkpoint_status = 'READY',
    min_valid_iat_epoch_ms = CASE
        WHEN min_valid_iat_epoch_ms IS NULL OR min_valid_iat_epoch_ms < #{newMinValidIatEpochMs}
        THEN #{newMinValidIatEpochMs}
        ELSE min_valid_iat_epoch_ms
    END,
    activated_at = CASE
        WHEN activated_at IS NULL THEN #{nowUtc}
        ELSE activated_at
    END,
    updated_by = #{updatedBy},
    updated_at = #{nowUtc}
WHERE checkpoint_key = #{checkpointKey}
  AND (
      checkpoint_status = 'UNINITIALIZED'
      OR (
          checkpoint_status = 'READY'
          AND min_valid_iat_epoch_ms IS NOT NULL
          AND min_valid_iat_epoch_ms >= 0
      )
  )

mapper.select:
SELECT revocation_id
FROM jwt_revocation
WHERE expires_at_epoch_ms <= #{cutoffEpochMs}
ORDER BY expires_at_epoch_ms ASC, revocation_id ASC
LIMIT #{batchSize}

mapper.delete:
DELETE FROM jwt_revocation
WHERE expires_at_epoch_ms <= #{cutoffEpochMs}
  AND revocation_id IN

    #{id}
